CREATE TABLE IF NOT EXISTS roles (id_rol SERIAL PRIMARY KEY, nombre VARCHAR(50) NOT NULL UNIQUE, descripcion VARCHAR(255));
CREATE TABLE IF NOT EXISTS usuarios (id_usuario SERIAL PRIMARY KEY, id_rol INT NOT NULL REFERENCES roles(id_rol), nombre VARCHAR(100) NOT NULL, correo VARCHAR(150) NOT NULL UNIQUE, contrasena_cifrada VARCHAR(255) NOT NULL, estado BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS clientes (id_cliente SERIAL PRIMARY KEY, nombre VARCHAR(100) NOT NULL, telefono VARCHAR(20), correo VARCHAR(150), fecha_registro TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS canchas (id_cancha SERIAL PRIMARY KEY, nombre VARCHAR(100) NOT NULL, tarifa_hora DECIMAL(10,2), estado VARCHAR(20) DEFAULT 'Disponible');
CREATE TABLE IF NOT EXISTS reservas (id_reserva SERIAL PRIMARY KEY, id_cancha INT NOT NULL REFERENCES canchas(id_cancha), id_cliente INT NOT NULL REFERENCES clientes(id_cliente), fecha DATE, hora_inicio TIME, hora_fin TIME, estado VARCHAR(20) DEFAULT 'Reservada', valor DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS mesas (id_mesa SERIAL PRIMARY KEY, numero INT NOT NULL, estado VARCHAR(20) DEFAULT 'Libre');
CREATE TABLE IF NOT EXISTS cuentas (id_cuenta SERIAL PRIMARY KEY, id_cliente INT REFERENCES clientes(id_cliente), id_mesa INT REFERENCES mesas(id_mesa), id_reserva INT REFERENCES reservas(id_reserva), id_usuario INT REFERENCES usuarios(id_usuario), fecha_apertura TIMESTAMP DEFAULT now(), fecha_cierre TIMESTAMP, estado VARCHAR(20) DEFAULT 'Abierta', total DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS categorias (id_categoria SERIAL PRIMARY KEY, nombre VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS productos (id_producto SERIAL PRIMARY KEY, id_categoria INT REFERENCES categorias(id_categoria), nombre VARCHAR(100) NOT NULL, precio_venta DECIMAL(10,2) NOT NULL, costo DECIMAL(10,2), stock_actual INT DEFAULT 0, stock_minimo INT DEFAULT 0, estado BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS promociones (id_promocion SERIAL PRIMARY KEY, nombre VARCHAR(100) NOT NULL, tipo VARCHAR(30), valor DECIMAL(10,2), fecha_inicio DATE, fecha_fin DATE, estado BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS detalle_cuenta (id_detalle SERIAL PRIMARY KEY, id_cuenta INT NOT NULL REFERENCES cuentas(id_cuenta), id_producto INT NOT NULL REFERENCES productos(id_producto), cantidad INT NOT NULL, precio_unitario DECIMAL(10,2), id_promocion INT REFERENCES promociones(id_promocion), subtotal DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS proveedores (id_proveedor SERIAL PRIMARY KEY, nombre VARCHAR(100) NOT NULL, telefono VARCHAR(20), correo VARCHAR(150), direccion VARCHAR(255));
CREATE TABLE IF NOT EXISTS compras (id_compra SERIAL PRIMARY KEY, id_proveedor INT NOT NULL REFERENCES proveedores(id_proveedor), id_usuario INT REFERENCES usuarios(id_usuario), fecha TIMESTAMP DEFAULT now(), total DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS detalle_compra (id_detalle_compra SERIAL PRIMARY KEY, id_compra INT NOT NULL REFERENCES compras(id_compra), id_producto INT NOT NULL REFERENCES productos(id_producto), cantidad INT NOT NULL, costo_unitario DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS movimientos_inventario (id_movimiento SERIAL PRIMARY KEY, id_producto INT NOT NULL REFERENCES productos(id_producto), tipo VARCHAR(20), cantidad INT, fecha TIMESTAMP DEFAULT now(), id_usuario INT REFERENCES usuarios(id_usuario), referencia VARCHAR(255));
CREATE TABLE IF NOT EXISTS pagos (id_pago SERIAL PRIMARY KEY, id_cuenta INT NOT NULL REFERENCES cuentas(id_cuenta), id_usuario INT REFERENCES usuarios(id_usuario), metodo VARCHAR(30), monto DECIMAL(10,2), fecha TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS egresos (id_egreso SERIAL PRIMARY KEY, concepto VARCHAR(255) NOT NULL, monto DECIMAL(10,2) NOT NULL, fecha TIMESTAMP DEFAULT now(), id_usuario INT REFERENCES usuarios(id_usuario));
CREATE TABLE IF NOT EXISTS auditoria (id_log SERIAL PRIMARY KEY, id_usuario INT REFERENCES usuarios(id_usuario), accion VARCHAR(100), tabla_afectada VARCHAR(100), fecha_hora TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS negocio (id_negocio INT PRIMARY KEY, nombre VARCHAR(100) NOT NULL, nit VARCHAR(30), direccion VARCHAR(150), telefono VARCHAR(20), logo TEXT, qr_pago VARCHAR(255));
CREATE TABLE IF NOT EXISTS comprobantes (id_comprobante SERIAL PRIMARY KEY, numero INT NOT NULL UNIQUE, tipo VARCHAR(10) DEFAULT 'Tirilla', id_cliente INT REFERENCES clientes(id_cliente), cliente_nombre VARCHAR(100), metodo VARCHAR(30) NOT NULL, subtotal DECIMAL(10,2) NOT NULL, descuento DECIMAL(10,2) DEFAULT 0, total DECIMAL(10,2) NOT NULL, estado VARCHAR(20) DEFAULT 'Pagado', id_usuario INT REFERENCES usuarios(id_usuario), id_reserva INT REFERENCES reservas(id_reserva), fecha TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS comprobante_items (id_item SERIAL PRIMARY KEY, id_comprobante INT NOT NULL REFERENCES comprobantes(id_comprobante), tipo VARCHAR(20) NOT NULL, descripcion VARCHAR(150) NOT NULL, id_producto INT REFERENCES productos(id_producto), id_promocion INT REFERENCES promociones(id_promocion), cantidad INT NOT NULL, precio_unitario DECIMAL(10,2) NOT NULL, descuento DECIMAL(10,2) DEFAULT 0, subtotal DECIMAL(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS notificaciones (id_notificacion SERIAL PRIMARY KEY, id_reserva INT REFERENCES reservas(id_reserva), telefono VARCHAR(20), mensaje TEXT, canal VARCHAR(20), estado VARCHAR(20), fecha TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS licencia (id INT PRIMARY KEY, clave TEXT NOT NULL, negocio VARCHAR(100), hardware VARCHAR(100), activada TIMESTAMP DEFAULT now());
